        if verb == "render":
            return self.game.render()
        if verb == "scores":                  # both totals, "P0 P1"
            return "%d %d" % (self.game.score(0), self.game.score(1))
        if verb == "over":
            return "yes" if self.game.is_over() else "no"
        if verb == "undo":                    # undo: "undone <move>" or "error: <message>"
            try:
                return "undone " + self.game.undo()
            except ValueError as e:
                return "error: " + str(e)
        if verb == "redo":                    # redo: the event text or "error: <message>"
            try:
                return self.game.redo()
            except ValueError as e:
                return "error: " + str(e)
        raise KeyError(verb)

